\label{def:CliqueInPossibleGraph} 
A set of vertices $C \subseteq V$ is a clique in a graph $G=(V,E)$, if
every pair of vertices in $C$ is connected by an edge in $E$.

\label{obs:Sub}
For any two vertex sets $A,B$ in $\mathcal{G}$, if $B \subset A$ then, 
$clq(B,\mathcal{G}) \ge clq(A,\mathcal{G})$.

\label{obs:Elim}
Let $C$ be an $\alpha$-clique in $\mathcal{G}$. Then for all $e \in E_C$ 
we have $p(e) \geq \alpha$.

\caption{MULE($\mathcal{G},\alpha$)}
\KwIn{$\mathcal{G} \mbox{ is the input uncertain graph}$}
\KwIn{$\alpha, 0 < \alpha < 1$ is the user provided probability threshold}
\label{algo:main}

$\hat{I} \leftarrow \emptyset$ \;
\ForAll{$u \in V$}
{
    $\hat{I} \leftarrow \hat{I} \cup \{  (u,1) \}$
}

Enum-Uncertain-MC($\emptyset$, 1 ,$\hat{I}$, $\emptyset$) \;

\caption{Enum-Uncertain-MC($C,q,I,X$)}
\KwIn{We assume $\mathcal{G}$ and $\alpha$ are available as immutable global variables} 
\KwIn{$C \mbox{ is the current Uncertain Clique being processed}$}
\KwIn{$q = clq(C,\mathcal{G})$, maintained incrementally}
\KwIn{$I \mbox{ is a set of all tuples} \left(u,r\right)$, such that $\forall (u,r) \in I$, $u > max(C)$, and $clq(C \cup \{ u\},\mathcal{G}) = q \cdot r \ge \alpha$, i.e. $C \cup \{ u \}$ is an $\alpha$-clique in $\mathcal{G}$}
\KwIn{$X \mbox{ is a set of all tuples} \left(v,s\right)$, such that $\forall (v,s) \in X$, $v \not \in C$, $v < max(C)$, and $clq(C \cup \{v\},\mathcal{G}) = q \cdot s \ge \alpha$ , i.e. $C \cup \{ v \}$ is an $\alpha$-clique in $\mathcal{G}$}
\label{algo:dfs}

        \If{$I = \emptyset$ and $X = \emptyset$} 
        {
            \label{algoline:check}
            Output $C$ as $\alpha$-maximal clique \label{algoline:out}  \;
            \Return
        }

	\ForAll{$ (u,r) \in I$ considered in increasing order of $u$}
	{
                \label{algoline:loop}
                $C' \leftarrow C \cup \{ u \}$ \tcp{Note $m = max(C') = u$} \label{algoline:genc} 
                $q' \leftarrow q \cdot r$  \tcp{$clq(C \cup \{ v \},\mathcal{G})$}  \label{algoline:prob}
                $I'  \leftarrow GenerateI(C',q',I)$ \; \label{algoline:genI}
                $X'  \leftarrow GenerateX(C',q',X)$ \; \label{algoline:genX}
                Enum-Uncertain-MC($C',q',I',X')$ \; \label{algoline:recursion}
                $X \leftarrow X \cup \{ (u,r) \}$ \label{algoline:addX}
        }

\caption{GenerateI($C',q',I$)}
\label{algo:generateI}
\KwIn{We assume $\mathcal{G}$ and $\alpha$ are available as immutable global variables} 

  $m \leftarrow max(C')$, $I' \leftarrow \emptyset$, $S \leftarrow \emptyset$ \;

  \ForAll{$(u,r) \in I$}
  {
    $S \leftarrow S \cup \{ u \}$   
  }

  $S \leftarrow S \cap \{ \Gamma(m) \}$

  \ForAll{$(u,r) \in I$}
  {
    \If{$u > m$ and $u \in S$}
    {
        $clq(C' \cup\{  u \},\mathcal{G}) \leftarrow q' \cdot r \cdot p(\{u,m\})$

        \If{$(clq(C' \cup\{  u \},\mathcal{G})) \ge \alpha$}
        {
          $u' \leftarrow u$ \;
          $r' \leftarrow r \cdot p(\{u,m\})$ \;
          $I' \leftarrow I' \cup  \{ (u',r') \}$ 
        }
    }
  }

  \Return I'

\caption{GenerateX($C',q',X$)}
\label{algo:generateX}
\KwIn{We assume $\mathcal{G}$ and $\alpha$ are available as immutable global variables} 

  $m \leftarrow max(C')$, $X' \leftarrow \emptyset$, $S \leftarrow \emptyset$ \;

  \ForAll{$(v,s) \in I$}
  {
    $S \leftarrow S \cup \{ v \}$   
  }

  $S \leftarrow S \cap \{ \Gamma(m) \}$

  \ForAll{$(v,s) \in X$}
  {
    \If{$v \in S$}
    {
      $clq(C' \cup\{  v \},\mathcal{G}) \leftarrow q' \cdot s \cdot p(\{v,m\})$

      \If{$(clq(C' \cup\{  v \},\mathcal{G}) \ge \alpha$}
      {
        $v' \leftarrow v$ \;
        $s' \leftarrow s \cdot p(\{v,m\})$ \;
        $X' \leftarrow X' \cup  \{ (v',s') \}$
      }
    }
  }

  \Return X'

\caption{LARGE--MULE($\mathcal{G},\alpha$,$t$)}
\KwIn{$\mathcal{G}' \mbox{ is the input uncertain graph post pruning}$}
\KwIn{$\alpha, 0 < \alpha < 1$ is the user provided probability threshold}
\KwIn{$t, t \ge 2$ is the user provided size threshold}
\label{algo:largemule}

$\hat{I} \leftarrow \emptyset$ \;
\ForAll{$u \in V$}
{
    $\hat{I} \leftarrow \hat{I} \cup \{  (u,1) \}$
}

Enum-Uncertain-MC-Large($\emptyset$, 1 ,$\hat{I}$, $\emptyset$,$t$) \;

\caption{Enum-Uncertain-MC-Large($C,q,I,X$,$t$)}
\KwIn{$C \mbox{ is the current Uncertain Clique being processed}$}
\KwIn{$q \mbox{ is pre-computed } clq(C,\mathcal{G})$}
\KwIn{$I \mbox{ is a set of tuples} \left(u,r\right)$, such that $\forall (u,r) \in I$, $u > \max(C)$, and $clq(C \cup \{ u\},\mathcal{G}) = q \cdot r \ge \alpha$, i.e. $C \cup \{ u \}$ is an $\alpha$-clique in $\mathcal{G}$}
\KwIn{$X \mbox{ is a set of tuples} \left(v,s\right)$, such that $\forall (v,s) \in X$, $v \not \in C$, $v < \max(C)$, and $clq(C \cup \{v\},\mathcal{G}) = q \cdot s \ge \alpha$ , i.e. $C \cup \{ v \}$ is an $\alpha$-clique in $\mathcal{G}$}
\KwIn{$t \mbox{ is the user provided size threshold}$}
\label{algo:large}

        \If{$I = \emptyset$ and $X = \emptyset$} 
        {
            Output $C$ as $\alpha$-maximal clique  \;
            \Return
        }

	\ForAll{$u,r \in I$ taken in lexicographical ordering of $u$}
	{
                $C' \leftarrow C \cup \{ u \}$ \tcp{Note $m = \max(C') = u$}  
                $q' \leftarrow q \cdot r$  \tcp{$clq(C \cup \{ v \},\mathcal{G})$}  
                $I'  \leftarrow GenerateI(C',q',I)$ \; 

                \If{$\left | C' \right | + \left | I' \right | < t$}
                {
                    continue \;
                }

                $X'  \leftarrow GenerateX(C',q',X)$ \; 
                Enum-Uncertain-MC-Large($C',q',I',X',t)$ \; 
                $X \leftarrow X \cup \{ (u,r) \}$ 
        }

\caption{DFS--NOIP($C$,$I$)}
\label{algo:naive}

$I_{copy} \leftarrow I$ \;

\ForAll{$u \in I_{copy}$}
{
    \If{$u \le max(C)$ OR $clq(C \cup \{ u \}) < \alpha$}
    {
        $I \leftarrow I \setminus \{ u \}$
    }
}

\If{$I = \emptyset$}
{
    \If{$C$ is an $\alpha$-maximal clique}
    {
        Output $C$ as $\alpha$-maximal clique \;
        \Return \;
    }
}

\ForAll{$v \in I$}
{

    $C' \leftarrow C \cup \{ v \}$ \;

    \If{$C'$ is an $\alpha$-maximal clique}
    {
        Output $C'$ as $\alpha$-maximal clique \;
    }
    \Else
    {
        $I' \leftarrow I \cap \Gamma( v )$ \;
        DFS--NOIP($C'$,$I'$) \;
    }
}
